    "description": "新华社利雅得11月24日电（记者罗晨 王海洲）沙特阿拉伯民防总局24日发表声明说，位于沙特首都利雅得阿卜杜拉国王金融区的一栋大楼当天遭到也门胡塞武装袭击，造成11人受伤。 声明所附图片显示，遭袭建筑为位于阿卜杜拉国王金融区的公共投资基金大厦，是利雅得目前最高的建筑。 这是该建筑一周内第二次遭袭。沙特阿拉伯民防总局19日发表声明说，利雅得最高建筑当天遭到也门胡塞武装袭击，但未造成人员伤亡。",
