    "content": "全球贸易、投资和科技领域正经历变革，令商业环境更加复杂、企业更难作出决策，而新加坡稳定的法律框架，能让企业对自身权利保障以及商业承诺得到履行抱持信心。 我国律政部长兼内政部第二部长唐振辉星期二（11月24日）在中国四川成都举行的一场活动上，鼓励四川企业在出海时利用新加坡的专业法律体系维护权益、解决争端。 他引述中国官方数据指出，目前约有8500家中国企业在新加坡运营，其中许多中企正利用本地商业和专业服务。新加坡国际仲裁中心（SIAC）最重要的用户群体之一也来自中国，许多中国律师和资深法律从业者担任了SIAC仲裁员。…"
