    "content": "新华社莫斯科11月24日电（记者黄河）俄罗斯国防部24日晚间发布通报称，俄武装部队当天使用无人机打击了为乌克兰武装部队提供保障的能源基础设施和海上船只。 通报称，俄军打击了位于乌克兰文尼察市、切尔尼戈夫州和罗夫诺州的三处变电站。在乌克兰敖德萨西南方向的黑海水域，俄军打击了一艘为乌军运送军民两用物资的干货船。 俄国防部24日上午发布通报称，过去一夜，俄防空部队在布良斯克州、别尔哥罗德州、卡卢加州等多个地区拦截并摧毁了699架乌克兰固定翼无人机。"
