    "content": "新华社波哥大11月24日电（记者李子健）据哥伦比亚媒体报道，该国中部梅塔省卫生部门24日凌晨说，该省政府大楼23日晚遭到爆炸袭击，已造成23人受伤。 报道说，爆炸产生的冲击波造成省政府大楼外立面的玻璃破碎、窗框受损。目前，尚无人员死亡的报告。 该省首府比亚维森西奥市市长亚历山大·巴克罗24日说，市政府和梅塔省政府将悬赏1.5亿哥伦比亚比索（约合4.3万美元）征集有关袭击者身份的线索。 哥伦比亚国防部同日发表声明谴责此次袭击，并表示军方和警方正采取相关行动，以查明并抓捕袭击者。 当地媒体此前报道说，爆炸疑似由汽车炸弹…"
