    "description": "一本发表于1946年的小说，如何在80年之后再次呈现在读者面前？ 近日，人民文学出版社联合新华文轩推出《围城》80周年布面精装典藏版。这一版本保留了两个不同时代的印记：装帧设计借鉴1947年上海晨光出版公司的初版，正文则沿用上世纪80年代人民文学出版社重新出版时，由钱锺书本人校改审定的版本。 新书采用桑麻布面精装，封面使用杨绛手书的“围城”二字，外配墨绿色布纹纸函套，函套书名字体复刻1947年初版样式。书的封底还隐藏着《周易》渐卦卦象。…",
    "content": "一本发表于1946年的小说，如何在80年之后再次呈现在读者面前？ 近日，人民文学出版社联合新华文轩推出《围城》80周年布面精装典藏版。这一版本保留了两个不同时代的印记：装帧设计借鉴1947年上海晨光出版公司的初版，正文则沿用上世纪80年代人民文学出版社重新出版时，由钱锺书本人校改审定的版本。 新书采用桑麻布面精装，封面使用杨绛手书的“围城”二字，外配墨绿色布纹纸函套，函套书名字体复刻1947年初版样式。书的封底还隐藏着《周易》渐卦卦象。此外，钱锺书在1982年为《围城》德译本撰写的前言手稿，此次也被复刻为四页折页随…"
