    "content": "（北京综合讯）中日关系持续紧张之际，中国国防部本周发纪录片，指控侵华日军当年有组织、成体系实施化学战，并在战后秘密遗弃化学武器。 《禁止化学武器公约》缔约国大会11月23日至27日在荷兰海牙举行，中国官方本月来持续施压日本，要求加快清查与销毁遗留在中国的化武。 中国国防部星期一（11月23日）晚发布30分钟纪录片《还我净土》，回顾侵华日军使用化学武器及战后在中国遗弃化武的历史，并记录中国参与清理日遗化武的过程。 纪录片介绍，作为二战日军最大化学武器生产基地的大久野岛，曾秘密制造逾6000吨化武毒气。中国当局处理日遗…"
