    "content": "台湾九合一选举进入最后冲刺阶段 ，今年多个县市选情激烈，蓝绿阵营候选人密集展开车队扫街，全力催票。台湾高铁投票日前夕至投票日当天上午的指定座席车票几乎售罄，选举疏运期间的售票数较四年前地方选举增加三成。学者分析，高铁订票热潮反映选情升温，但投票率提高对各地选情的影响，仍须视返乡选民的分布而定。 台湾将于星期六（11月28日）举行九合一选举，其中将选出全台22县市的地方首长。今年六都中，新北、台中、台南及高雄市长皆任期届满卸任，台北市长蒋万安和桃园市长张善政则寻求连任。 根据公开竞选行程，国民党和民进党县市长候选人星…"
