    "content": "新华社河内11月24日电（记者胡佳丽 邹学冕）由中国人权研究会、中国驻越南大使馆、中国外文局和越南胡志明国家政治学院人权研究院共同主办的《习近平关于尊重和保障人权论述摘编》学术研讨会24日在越南首都河内举行。中越两国30多位专家学者参加会议，围绕促进和保障人权的理念和实践经验交流研讨。 中国驻越南大使馆公使衔参赞常久青在致辞中说，中国共产党坚持以人民为中心，在推进经济社会发展和改善人民生活方面取得重要成就，走出一条具有中国特色的人权发展道路。中越开展人权领域学术交流，有助于深化治国理政交流互鉴，推进符合各自国情的人…"
