    "content": "新华社华盛顿11月24日电 据美国《华尔街日报》24日援引知情人士消息报道，为缓解无人作战装备短缺问题，美国防部正与通用汽车公司、福特汽车公司等制造商洽谈，寻求其协助大规模生产军用无人机。 报道指出，美军方希望利用汽车行业庞大的装配线以提升关键弹药和装备的产量。美国防部领导层意识到，许多美国无人机公司规模小且缺乏经验和产能，无法满足国防部未来几年数百万架无人机的采购需求。国防部近几个月一直在争取利用汽车制造商成熟的供应链，提升从导弹到战术卡车等各类武器的产量。 报道还称，美国防部长赫格塞思已于今年秋季成立一个作战司…"
