    "description": "新华社耶路撒冷/加沙11月24日电（记者庞昕熠 徐泽宇）以色列看守政府总理内塔尼亚胡与国防部长卡茨24日发表联合声明称，巴勒斯坦伊斯兰抵抗运动（哈马斯）内部安全机构负责人纳伊姆·阿布·纳赫勒已被以色列国防军打死。 巴勒斯坦安全部门和卫生部门的消息人士24日告诉新华社记者，以色列军队当天袭击加沙地带多地，造成至少7名巴勒斯坦人死亡，其中包括一名哈马斯指挥官。据加沙地带内政部门24日发表的声明，这名指挥官是纳伊姆·阿布·纳赫勒。",
    "content": "新华社耶路撒冷/加沙11月24日电（记者庞昕熠 徐泽宇）以色列看守政府总理内塔尼亚胡与国防部长卡茨24日发表联合声明称，巴勒斯坦伊斯兰抵抗运动（哈马斯）内部安全机构负责人纳伊姆·阿布·纳赫勒已被以色列国防军打死。 巴勒斯坦安全部门和卫生部门的消息人士24日告诉新华社记者，以色列军队当天袭击加沙地带多地，造成至少7名巴勒斯坦人死亡，其中包括一名哈马斯指挥官。据加沙地带内政部门24日发表的声明，这名指挥官是纳伊姆·阿布·纳赫勒。"
