    "content": "新华社北京11月24日电 以色列交通部23日发表声明说，该部门已批准迪拜航空公司恢复往来以色列航班的申请，目前在等以安全部门的最终审核。 声明说，以交通部日前向阿联酋派出一支代表团，评估迪拜航空在9月安全事件后所采取的应对措施。交通部长米丽·雷格夫听取相关汇报后，决定批准迪拜航空复飞往返迪拜与特拉维夫之间的航线。 9月30日，一架载有迪拜航空涉事航班乘客的替代航班即将降落在以色列特拉维夫的本-古里安国际机场。新华社发（吉尔·科恩·马根摄） 9月30日，迪拜航空FZ1073航班从阿联酋迪拜飞往以色列特拉维夫途中，副驾…"
