    "content": "新华社上海11月24日电（记者樊相龙）24日在上海举行的2026年6G发展大会上，工业和信息化部与北京市、河北省、上海市、江苏省、浙江省、安徽省、湖北省、广东省等8个试点省（市），共同启动6G创新发展部省协同试点工作。 记者从会上获悉，工业和信息化部组织开展6G创新发展部省协同试点专项行动，通过国家统筹协调、地方差异推进、多方积极参与的组织模式，推动形成全国6G创新“一盘棋”格局。 据工业和信息化部总工程师钟志红介绍，中国高度重视6G创新发展，积极参与国际标准制定，大力推进6G研发和产业培育，取得积极进展。当前，6…"
