    "content": "新华社海口11月24日电 题：礁石不语 守海有声——记“最美新时代革命军人”、海南省军区某部军官张峰 杨茹、贾启龙、阳宗峰 南海风起。浪头一次次涌上来，碎在礁石上。伫立岸边，举起望远镜，张峰警觉地望向远方。 这片海，张峰守了14年。身为海南省军区某部军官，他常说：“这片‘祖宗海’，我们得守好，这是祖国和人民交给我们的任务。” 家 船，在浪里起起伏伏。 第一次上岛，张峰用了整整17个小时。这一趟，不为赶路，是为“安家”。 2012年，一个向海而生的新单位选人，急需骨干力量。消息传来，在某县武装部任政治委员的张峰主动报…"
