    "content": "新华社伦敦11月24日电（记者高文成）英国海上贸易行动办公室24日通报说，三艘船只23日晚在向东通过霍尔木兹海峡时遭不明发射物击中。三艘船随后继续航行，所有船员无人失踪。 根据通报，事件发生于协调世界时23日20时25分（北京时间24日4时25分）。船只受损情况和事件对环境的影响尚在调查。 该办公室24日早些时候还通报说，协调世界时22日10时26分（北京时间22日18时26分），一艘散货船在阿拉伯联合酋长国迪巴港外锚泊时，左舷遭不明发射物击中，船上起火。截至通报发布时，尚无人员伤亡报告。 近期，霍尔木兹海峡及周边…"
