    "description": "新华社广州11月24日电（记者邓瑞璇）以“为资金找项目、为项目找资金”为主题的2026粤港澳大湾区文化产业投资大会24日在广州开幕。大会由粤港澳三地联合举办，聚焦“AI+文化”搭建产融对接平台，推动文化、科技和金融深度耦合，赋能文化新质生产力发展。 24日举行的文化产业投资主题大会上，暨南大学产业经济研究院院长陶锋发布《2026年粤港澳大湾区文化产业投资趋势报告》，系统研判大湾区文化产业的投资风向与增长规律。“大湾区文化产业的发展定位应…",
    "content": "新华社广州11月24日电（记者邓瑞璇）以“为资金找项目、为项目找资金”为主题的2026粤港澳大湾区文化产业投资大会24日在广州开幕。大会由粤港澳三地联合举办，聚焦“AI+文化”搭建产融对接平台，推动文化、科技和金融深度耦合，赋能文化新质生产力发展。 24日举行的文化产业投资主题大会上，暨南大学产业经济研究院院长陶锋发布《2026年粤港澳大湾区文化产业投资趋势报告》，系统研判大湾区文化产业的投资风向与增长规律。“大湾区文化产业的发展定位应顺应全球湾区演进趋势。粤港澳大湾区兼具制造业根基与科技创新优势，应探索制造与创新…"
