    "content": "中新网杭州11月24日电(蓝伊旎)11月24日，民建浙江省第十届委员会第六次全体会议在浙江杭州举行。民建浙江省委会主委陈小平作工作报告时介绍，过去一年，浙江民建一体推进“同心向党、同心共富、同心同廉、强基固本”四大工程，各项工作取得新进展、新成效。"
