    "content": "新华社成都11月24日电 题：县域内住院率超90%——四川这样拓展“三明医改” 新华社记者董小红、李恒 优化医疗资源布局，下沉优质健康服务，全省县域内住院率超90%……11月24日，记者在国家卫生健康委于四川省自贡市举行的因地制宜推广三明医改经验有关情况新闻发布会上了解到，作为全国深化医疗服务价格改革试点省，四川自试点以来调整医疗服务价格超过4000项，医疗服务收入占比提升至36.5%，以公益导向持续深化公立医院改革。 “立足四川人口多、群众健康需求大的省情实际，我们坚持高位推动，健全‘三医’协同发展和治理体系。”…"
