    "content": "新华社北京11月24日电（记者温竞华）第四届世界材料大会将于2027年1月24日至27日在海南举办，开展覆盖45个前沿热点方向的高端学术对话，全球顶尖科学家与产业创新力量将充分交流材料科学基础前沿、颠覆性技术的最新进展，共商材料科技未来发展。 这是记者从11月24日举行的第四届世界材料大会新闻吹风会上获得的信息。 据介绍，本届大会以构建人类命运共同体理念为引领，以全球材料发展问题为核心主线，45个论坛分属能源材料、先进信息材料、先进结构材料、先进功能材料、生物材料、计算材料、特别专题、青年科学家大会8个类别。 大会…"
