    "title": "10月全国查处违反中央八项规定精神问题28934起",
    "link": "http://www.news.cn/20261124/2b68606ce0264c7594923c3310f1acad/c.html",
    "pub_date": "2026-11-24 20:27:39",
    "author": "",
    "description": "新华社北京11月24日电（记者孙少龙）中央纪委国家监委24日公布全国查处违反中央八项规定精神问题情况月报数据。通报显示，今年10月，全国共查处违反中央八项规定精神问题28934起，批评教育和处理35193人（包括2名省部级干部、98名地厅级干部），给予党纪政务处分23996人。 根据通报，今年10月全国共查处形式主义、官僚主义问题15414起，批评教育和处理19619人。其中，查处“在履职尽责、服务经济社会发展和生态环境保护方面不担当、…",
    "content": "新华社北京11月24日电（记者孙少龙）中央纪委国家监委24日公布全国查处违反中央八项规定精神问题情况月报数据。通报显示，今年10月，全国共查处违反中央八项规定精神问题28934起，批评教育和处理35193人（包括2名省部级干部、98名地厅级干部），给予党纪政务处分23996人。 根据通报，今年10月全国共查处形式主义、官僚主义问题15414起，批评教育和处理19619人。其中，查处“在履职尽责、服务经济社会发展和生态环境保护方面不担当、不作为、乱作为、假作为，严重影响高质量发展”方面问题最多，查处13020起，批评…"
