    "title": "库克群岛科学家搭乘中国“蛟龙”号载人潜水器成功下潜",
    "link": "https://www.chinanews.com.cn/gn/2026/11-24/10737166.shtml",
    "pub_date": "2026-11-24 20:02:31",
    "author": "",
    "description": "中新社北京11月24日电 (记者 阮煜琳)记者24日从中国自然资源部获悉，中国载人潜水器“蛟龙”号日前在库克群岛专属经济区马尼希基断裂带海域成功完成下潜作业，来自库克群岛的科学家搭乘中国载人潜水器开展环境调查。",
