    "content": "新华社基辅11月24日电 据美国彭博社24日报道，乌克兰总统泽连斯基在接受该媒体采访时证实，乌方21日在芬兰湾袭击了俄罗斯一艘货船。 泽连斯基称，“任何悬挂俄罗斯国旗的船只，任何在俄罗斯领海或中立水域载有武器或任何受制裁货物的（俄）船只，都是我们的合法打击目标”。 泽连斯基还称，俄罗斯货船“斯巴达2号”载有武器，是乌军可以打击的目标。但他承认，此次袭击“可能令一些盟友感到不安”。 芬兰国防部21日发布公告说，芬兰边防军当天上午在芬兰湾东部国际水域监测到俄罗斯货船“斯巴达2号”船体受损并起火，疑遭无人机袭击。俄罗斯列…"
