    "content": "新华社香港11月24日电 香港特区政府创新科技署24日宣布，在InnoHK创新香港研发平台成立香港海洋智能和可持续发展研究中心，由香港大学联合崂山实验室，并与中国海洋大学、加州大学伯克利分校、香港城市大学、香港科技大学、物流及供应链多元技术研发中心等合作运行。 创新科技署发言人表示，为积极对接国家“十五五”规划，香港五年规划提出加快建设国际创科中心，巩固提升国际航运中心地位，推动智慧绿色港口发展，完善物流数据互联互通，并壮大海洋经济等具战略价值的新兴产业；同时，积极探讨开发海洋探索等新科技领域，鼓励“产、学、研”协…"
