    "content": "流感等急性呼吸道传染病已进入流行季。中国流感监测周报最新数据显示，当前全国检出流感阳性样本中，甲型H1N1占比56.2%、甲型H3N2占比15.5%、乙型Victoria系占比28.3%。 三种毒株同时流行意味着什么？公众如何科学应对？现在接种流感疫苗来得及吗？记者采访相关专家并走访基层医疗机构。 三种毒株流行意味着什么？不必过度紧张 中国疾控中心病毒病所研究员辛丽说，在同一个流感流行季中，可能会有两种及以上的不同病毒型别或亚型共同或交替流行，不同亚型之间缺乏有效的交叉保护，感染过其中一种后，仍可能再感染其他类型的…"
