    "content": "新华社北京11月24日电（记者王立彬）继2025年联合海洋科学考察航次之后，中国、库克群岛两国联合实施2026年海洋科学考察航次，库克群岛科学家搭乘我国“蛟龙”号载人潜水器成功下潜。 “蛟龙”号潜返后中外科学家合影（纪晔摄） 记者11月24日从自然资源部获悉，本航次期间，“蛟龙”号计划在库克群岛专属经济区开展5个潜次任务，通过本航次调查既帮助库克群岛填补本国深海基础数据空白，也为其培养首批具备载人深潜参与经验的本土科研人员。 据介绍，11月21日（船时，西十区），“蛟龙”号载人潜水器在库克群岛专属经济区马尼希基断裂…"
