    "description": "36氪获悉，长华集团发布股票交易风险提示，公司为汽车零部件上市公司，主要从事汽车金属零部件的研发、生产与销售，核心产品为紧固件、冲焊件，不从事人形机器人整机业务，仅为客户提供执行器专用结构件等相关部件产品，截至目前实现营业收入约8.8万元，上述产品是基于公司主营业务产品应用场景的拓展，占公司总营业收入的比例极小，对净利润无重大影响。关于行星滚柱丝杠产品，目前仍处于研发阶段，尚未获得客户定点，也未实现营业收入，对业绩不构成影响。",
    "content": "36氪获悉，长华集团发布股票交易风险提示，公司为汽车零部件上市公司，主要从事汽车金属零部件的研发、生产与销售，核心产品为紧固件、冲焊件，不从事人形机器人整机业务，仅为客户提供执行器专用结构件等相关部件产品，截至目前实现营业收入约8.8万元，上述产品是基于公司主营业务产品应用场景的拓展，占公司总营业收入的比例极小，对净利润无重大影响。关于行星滚柱丝杠产品，目前仍处于研发阶段，尚未获得客户定点，也未实现营业收入，对业绩不构成影响。"
