    "content": "新华社德黑兰11月24日电（记者刁慧琳 沙达提）据伊朗伊斯兰共和国广播电视台24日报道，伊朗伊斯兰共和国军队总司令哈塔米当天表示，在伊朗提出的七项条件得到落实之前，伊方不仅不会开放霍尔木兹海峡，还将进一步收紧对海峡的封锁。 哈塔米当天在伊朗伊斯兰共和国军队指挥和参谋大学发表讲话时说，霍尔木兹海峡对伊朗具有地缘政治意义，也是伊朗国家力量体系的重要一环。他向伊朗海军司令沙赫拉姆·伊拉尼下达指令，要求“逐日收紧对霍尔木兹海峡的封锁”，加强对海峡的管控，“使敌方面临更加艰难的处境”。 哈塔米说，“伊朗不会独自承受战争之苦，…"
