    "description": "新华社北京11月24日电 美国一家联邦巡回上诉法院23日批准美国陆军于25日在艾奥瓦州引爆销毁约4.3吨已发生化学降解的叠氮化铅。这一有毒危险物质用于制造起爆药。一些环保组织担忧销毁行动导致铅污染，曾要求法院予以阻止。 据美联社和路透社等媒体报道，联邦第八巡回上诉法院一个三人合议庭23日撤销该法院19日颁布的引爆作业暂停令，理由是美国环境保护署回应原告方的担忧，已紧急采取将铅尘散播最小化的适当措施，包括设置围栏、环境监控采样。 美国陆军…",
    "content": "新华社北京11月24日电 美国一家联邦巡回上诉法院23日批准美国陆军于25日在艾奥瓦州引爆销毁约4.3吨已发生化学降解的叠氮化铅。这一有毒危险物质用于制造起爆药。一些环保组织担忧销毁行动导致铅污染，曾要求法院予以阻止。 据美联社和路透社等媒体报道，联邦第八巡回上诉法院一个三人合议庭23日撤销该法院19日颁布的引爆作业暂停令，理由是美国环境保护署回应原告方的担忧，已紧急采取将铅尘散播最小化的适当措施，包括设置围栏、环境监控采样。 美国陆军3月在位于艾奥瓦州小城米德尔敦的陆军弹药厂发现，68桶叠氮化铅因长期存放，桶内维…"
