    "content": "新华社北京11月24日电 一列客运列车22日晚在美国路易斯安那州拉斐特市以东与一辆重型卡车相撞，列车部分脱轨，5名乘客受轻伤。 事故列车由美国全国铁路客运公司运营。该公司发表声明说，列车载有95名乘客，当地时间22日18时15分左右与卡车相撞，列车车头和两节行李车厢脱轨。当地媒体援引调查人员的话报道，重型卡车当时运载一辆推土机，穿过铁路道口时卡在铁轨上，列车未能及时停下，与卡车相撞。 拉斐特市消防部门说，消防人员确认现场安全后，协助乘客携带行李撤至安全地带。全国铁路客运公司表示，涉事线路暂时停运，将为乘客安排大巴，…"
