    "description": "新华社济南11月24日电 题：山东昌邑：古韵今风织锦绣 新华社记者邵琨 走进位于山东潍坊市的昌邑华晨纺织印染有限公司，桌子上展陈着用于染色的茶叶、五倍子、大青叶等植物原料以及染色后的彩色丝绸。板蓝根染出靛蓝，茜草染出赭红，栀子染出明黄，苏木染出醇厚的红。每种植物染出的颜色都对应一个好听的名字：生命绿、栀子黄、豆沙紫…… 用于染色的植物和染色后的初加工产品。新华社记者邵琨 摄 取用不同植物的不同部位，可以染出不同的颜色。同一种植物染料因取…",
    "content": "新华社济南11月24日电 题：山东昌邑：古韵今风织锦绣 新华社记者邵琨 走进位于山东潍坊市的昌邑华晨纺织印染有限公司，桌子上展陈着用于染色的茶叶、五倍子、大青叶等植物原料以及染色后的彩色丝绸。板蓝根染出靛蓝，茜草染出赭红，栀子染出明黄，苏木染出醇厚的红。每种植物染出的颜色都对应一个好听的名字：生命绿、栀子黄、豆沙紫…… 用于染色的植物和染色后的初加工产品。新华社记者邵琨 摄 取用不同植物的不同部位，可以染出不同的颜色。同一种植物染料因取材时间、季节不同，色相也有所不同。昌邑华晨纺织印染有限公司办公室主任陈龙勇说：“…"
