    "pub_date": "2026-11-24 18:49:23",
    "author": "",
    "description": "记者日前获悉，由中国东方演艺集团有限公司等出品的舞剧《经山海》将于2027年初与观众见面。 《山海经》是中华民族古老的神话基因库，是华夏先民对天地万物的浪漫想象。舞剧《经山海》取“经行山海，观物照心”之意，将夸父逐日的经典传说作为核心叙事主线，以行旅式的叙事脉络串联起山海间的奇景异兽、奇幻际遇。 舞剧《经山海》海报 （中国东方演艺集团提供） “作为国家级演艺院团，集团始终以传承中华优秀传统文化、用艺术讲好中国故事为己任。”中国东方演艺集…",
    "content": "记者日前获悉，由中国东方演艺集团有限公司等出品的舞剧《经山海》将于2027年初与观众见面。 《山海经》是中华民族古老的神话基因库，是华夏先民对天地万物的浪漫想象。舞剧《经山海》取“经行山海，观物照心”之意，将夸父逐日的经典传说作为核心叙事主线，以行旅式的叙事脉络串联起山海间的奇景异兽、奇幻际遇。 舞剧《经山海》海报 （中国东方演艺集团提供） “作为国家级演艺院团，集团始终以传承中华优秀传统文化、用艺术讲好中国故事为己任。”中国东方演艺集团党委书记、董事长景小勇表示，《山海经》是古人写下的天地，是流淌在中国人文化血脉…"
