    "description": "中欧上月达成协议后再起贸易波折，欧盟星期二（11月24日）宣布临时保障措施，对来自中国及其他地区的混合动力汽车进口采取配额限制。中国商务部同日呼吁布鲁塞尔遵守双方共识，并强调坚决维护中国相关产业正当权益。 据彭博社、路透社等报道，欧盟执行机构欧洲委员会星期二发布官方公报，当中通报临时措施将于12月1日至明年6月18日实施，在此期间中国混动汽车的进口上限设定为19万1780辆。 星期二出台的保障措施也将影响欧盟其他主要贸易伙伴。在此期间，…",
    "content": "中欧上月达成协议后再起贸易波折，欧盟星期二（11月24日）宣布临时保障措施，对来自中国及其他地区的混合动力汽车进口采取配额限制。中国商务部同日呼吁布鲁塞尔遵守双方共识，并强调坚决维护中国相关产业正当权益。 据彭博社、路透社等报道，欧盟执行机构欧洲委员会星期二发布官方公报，当中通报临时措施将于12月1日至明年6月18日实施，在此期间中国混动汽车的进口上限设定为19万1780辆。 星期二出台的保障措施也将影响欧盟其他主要贸易伙伴。在此期间，日本的汽车进口上限为17万零889辆，土耳其为12万6320辆，英国为10万54…"
