    "description": "辽宁锦州的冬天是被早市唤醒的。寒风凛冽，裹紧衣服钻进石桥子早市，肉夹、炸枣、豆浆油条、羊汤面茶，热气裹着吆喝声在摊位间流淌，身心跟着味蕾热乎起来。 这个由摊贩自发形成的早市，横跨四个街区，绵延1.2公里，汇聚超过1400个摊位，除各式小吃摊，还有果蔬、海鲜等特色农产品。如今，这里既是当地市民尝鲜的去处，也是外地游客感受烟火、满载而归的地方。 一名摊主在辽宁省锦州市石桥子早市售卖蔬菜。新华社记者潘昱龙 摄 今年10月，以锦州为主要取景地的…",
    "content": "辽宁锦州的冬天是被早市唤醒的。寒风凛冽，裹紧衣服钻进石桥子早市，肉夹、炸枣、豆浆油条、羊汤面茶，热气裹着吆喝声在摊位间流淌，身心跟着味蕾热乎起来。 这个由摊贩自发形成的早市，横跨四个街区，绵延1.2公里，汇聚超过1400个摊位，除各式小吃摊，还有果蔬、海鲜等特色农产品。如今，这里既是当地市民尝鲜的去处，也是外地游客感受烟火、满载而归的地方。 一名摊主在辽宁省锦州市石桥子早市售卖蔬菜。新华社记者潘昱龙 摄 今年10月，以锦州为主要取景地的电视剧《小城良方》播出。戏里戏外，锦州这座东北小城持续“出圈”。电视剧呈现烟火里…"
