    "author": "",
    "description": "新华社旧金山11月23日电 综述｜黄仁勋复职 英伟达争议未止 新华社记者吴晓凌 美国芯片制造商英伟达公司23日宣布，恢复公司联合创始人黄仁勋的总裁、首席执行官及董事会成员职务。分析人士认为，英伟达董事会在短时间内改变立场，反映出黄仁勋在公司战略决策和人工智能（AI）产业链中的影响力，更凸显了美国政府立场、投资者利益与企业治理原则之间的复杂博弈。 英伟达公司董事长哈维·琼斯17日曾明确表示，董事会无意恢复黄仁勋职务。仅仅几天后，英伟达董事…",
    "content": "新华社旧金山11月23日电 综述｜黄仁勋复职 英伟达争议未止 新华社记者吴晓凌 美国芯片制造商英伟达公司23日宣布，恢复公司联合创始人黄仁勋的总裁、首席执行官及董事会成员职务。分析人士认为，英伟达董事会在短时间内改变立场，反映出黄仁勋在公司战略决策和人工智能（AI）产业链中的影响力，更凸显了美国政府立场、投资者利益与企业治理原则之间的复杂博弈。 英伟达公司董事长哈维·琼斯17日曾明确表示，董事会无意恢复黄仁勋职务。仅仅几天后，英伟达董事会便作出截然相反的决定。外界普遍认为，美国政府的态度是促成这一转变的重要因素。 …"
