    "author": "",
    "description": "这场风波真正留下的考题，并不会随着CEO重新坐回办公室而消失。 南方周末研究员 胡启元 责任编辑：孙孝文 11天内，英伟达董事会对黄仁勋的去留，作出了两次截然不同的决定。 当地时间11月12日，英伟达董事会接受黄仁勋辞去总裁兼首席执行官职务，并任命临时CEO。几天后，董事会明确表示无意让黄仁勋复职。 11月23日，英伟达宣布，董事会全票同意黄仁勋复职。公告称，董事会对黄仁勋的坦诚和领导英伟达的能力感到满意；同时，董事会也听取了美国政府高…",
    "content": "这场风波真正留下的考题，并不会随着CEO重新坐回办公室而消失。 南方周末研究员 胡启元 责任编辑：孙孝文 11天内，英伟达董事会对黄仁勋的去留，作出了两次截然不同的决定。 当地时间11月12日，英伟达董事会接受黄仁勋辞去总裁兼首席执行官职务，并任命临时CEO。几天后，董事会明确表示无意让黄仁勋复职。 11月23日，英伟达宣布，董事会全票同意黄仁勋复职。公告称，董事会对黄仁勋的坦诚和领导英伟达的能力感到满意；同时，董事会也听取了美国政府高层的意见，并据此确认黄仁勋复职不存在国家安全风险。 美国总统特朗普在周一接受采访…"
