    "content": "新华社成都11月24日电 题：以党建凝聚小区治理“向心力” 新华社记者刘祯、李倩薇 绿植葱郁，步道整洁，景观池水光潋滟……近日，记者走进四川省成都市高新区中和街道观东社区中铁城锦南汇小区，一派宜居舒心、和谐美好的景象映入眼帘。 “小区的每一处景观、每一处设施设备都是大家一点点努力的结果。”观东社区党委书记、居委会主任翁菁说。 很难想象，眼前这个环境清幽的小区，曾面临人口多、需求多、矛盾多、公共空间少的困境。电梯故障频发、电瓶车乱停乱放、停车费过高、公共收益不透明等问题长期得不到解决，物业和业主之间的关系紧张，投诉率…"
